/* ASK 378: a judge is counted when it is not truncated and has no uncured debate rule violation (derive_debate_outcome's own test); a judge line says which, and why. */
const drvUnc = raw => { const out = [], seen = new Set(); for (const m of String(raw || '').matchAll(/\[AUDIT v21: DEBATE RULE VIOLATION REPORT -- ([^\n]*?)\](?=\s*(?:\n|$|\\n))/g)) { const p = m[1].split(/(?:^|; )(SEAT|ITEM|RULE|RESULT|KINDS|WHY|LINE|STATEMENT|JUDGE STATEMENT): /); const o = {}; for (let i = 1; i < p.length; i += 2) o[p[i]] = p[i + 1];
  if (o.RESULT !== 'UNCURED' || !o.ITEM || !o.RULE) continue; const w = String(o.WHY || ''); if (/^TRIAL rule \(recorded and answered/.test(w) || /^RECORD-ONLY \(/.test(w)) continue; const k = o.RULE + '|' + o.ITEM; if (seen.has(k)) continue; seen.add(k); out.push(o.RULE + ' on ' + o.ITEM); } return out; };
const isCounted = j => !j.truncated && (+j.drv_uncured || 0) === 0 && /^(HELD|PARTIAL|BROKEN)$/.test(String(j.verdict_tag || ''));
const notCountedWhy = j => { if (j.truncated) return 'NOT COUNTED: the reply was cut off (truncated)'; const n = +j.drv_uncured || 0; if (n > 0) { const L = drvUnc(j.verdict_raw); return 'NOT COUNTED: ' + n + ' debate rule violation' + (n === 1 ? '' : 's') + ' not cured' + (L.length ? ' (' + L.join('; ') + ')' : '') + (L.length !== n ? '; ' + (L.length ? L.length + ' of the ' + n + ' are' : 'none is') + ' named in the judgment\'s own record' : ''); } return 'NOT COUNTED: its verdict could not be read'; };
const recompNote = raw => { const s = String(raw || '').replace(/\\"/g, '"'); const p = []; const v = s.match(/\b(HELD|PARTIAL|BROKEN) \(recomputed by the engine; the judge wrote (HELD|PARTIAL|BROKEN)\)/); if (v) p.push('the engine recomputed its verdict after the cure: the judge wrote ' + v[2] + ', and it counts as ' + v[1]);
  const a = s.match(/\[AUDIT v25: RECOMPUTED AFTER CURE -- [^\n]*?ORIGINAL: [^;]*?RESULT ([A-Z][A-Z ]*?); RECOMPUTED: [^;]*?RESULT ([A-Z][A-Z ]*?);/); if (a && a[1] !== a[2]) p.push((v ? 'its RESULT was also recomputed' : 'the engine recomputed its RESULT after the cure') + ': the judge wrote ' + a[1] + ', and it reads ' + a[2]); return p.length ? '. ' + p.join('; ').replace(/^./, c => c.toUpperCase()) : ''; };
const TR = []; J.concat(Array.isArray(r.drv_removed) ? r.drv_removed : []).forEach(q => { for (const m of String(q.verdict_raw || '').matchAll(/\[AUDIT v21: ALTERNATE TRIED -- SEAT: ([^;\]]+); ALTERNATE: ([^;\]]+); MODEL: ([^;\]]+); RESULT: ([A-Z ]+?)(?:; WHY: ([^\n]*?))?\](?=\s*(?:\n|$|\\n))/g)) TR.push({ seat: m[1].trim(), alt: m[2].trim(), result: m[4].trim(), why: m[5] || '' }); });
  const trWhy = x => x.result !== 'NOT SEATED' ? x.result.toLowerCase() : /content null|NO ROW IS WRITTEN|no JSON|empty reply|timed? ?out|error/i.test(x.why) ? 'no verdict returned' + ((x.why.match(/finish_reason (\w+)/) || [])[1] ? ' (finish_reason ' + x.why.match(/finish_reason (\w+)/)[1] + ')' : '') : (x.why.match(/(\d+) uncured item/) ? 'not seated (' + x.why.match(/(\d+) uncured item/)[1] + ' uncured items)' : 'not seated' + (x.why ? ': ' + x.why.replace(/\s+/g, ' ').slice(0, 160) : ''));
const placeOf = j => { const DRx = (Array.isArray(r.drv_removed) ? r.drv_removed : []).find(x => x.replaced_by === j.judge_seat); if (DRx) return DRx.seat; const x = TR.find(y => y.result === 'SEATED' && y.alt === j.judge_seat && y.seat !== y.alt); return x ? x.seat : null; };
SEATS.forEach(e => { if (e.removed) { const x = e.removed; t += '- Panel judge ' + e.n + ': ' + nm(x.seat) + ' (' + (x.api_model || '') + '): **' + (x.verdict_tag || '?') + '**' + VSIDE + ' (removed: ' + (x.drv_uncured || 0) + ' debate rule violation(s) not cured; not counted; ' + (ALTN0[x.replaced_by] || nm(x.replaced_by)) + ' sat in its place)\n'; return; }
  const j = e.j; const why = curedTo(j.verdict_raw) ? null : seatReason(j.verdict_raw); const counted = isCounted(j); t += '- Panel judge ' + e.n + e.tag + ': ' + nm(j.judge_seat) + ' (' + (j.judge_api_model || '') + '): **' + (j.verdict_tag || '?') + '**' + VSIDE + ' (' + (counted ? 'counted' : notCountedWhy(j)) + (placeOf(j) ? '; sat in ' + nm(placeOf(j)) + '\'s place' : '') + ')' + recompNote(j.verdict_raw) + (why ? '. Reason: ' + why : '') + '\n'; });
if (!J.length) t += '- No panel judgments recorded\n';
{   const FILL = new Set(TR.filter(x => x.result === 'SEATED' && J.some(q => q.judge_seat === x.alt && isCounted(q))).map(x => x.seat + '>' + x.alt));
  const fillOf = s => J.find(q => isCounted(q) && FILL.has(s + '>' + q.judge_seat));
  const GN = [...new Set(SEATS.map(e => e.n))].filter(n => { const G = SEATS.filter(e => e.n === n); return !(G.length === 1 && G[0].j && !G[0].tag && TR.some(x => x.result === 'SEATED' && x.alt === G[0].j.judge_seat && x.seat !== x.alt)); });
  const NSEAT = GN.length, NC = GN.filter(n => { const G = SEATS.filter(e => e.n === n); const f = G[0]; const s = f.removed ? f.removed.seat : f.j.judge_seat; return G.some(e => e.j && isCounted(e.j)) || !!fillOf(s); }).length;
  t += '- Panel result: **' + (r.panel_verdict || '?') + '**' + (r.panel_split ? ' (' + r.panel_split + ')' : '') + VSIDE + (NSEAT ? '. Counted: ' + NC + ' of ' + NSEAT + ' panel seat' + (NSEAT === 1 ? '' : 's') + ' (a seat counts when its judge, or the alternate seated in its place, is counted).' : '') + '\n';
  GN.forEach(n => { const G = SEATS.filter(e => e.n === n); if (G.some(e => e.j && isCounted(e.j))) return; const f = G[0]; const s = f.removed ? f.removed.seat : f.j.judge_seat; if (fillOf(s)) return; const tr = TR.filter(x => x.seat === s); const seen = new Set(); const tl = tr.filter(x => !seen.has(x.alt) && seen.add(x.alt));
    t += '- Panel judge ' + n + '\'s seat stayed empty: ' + nm(s) + ' was not counted, and no judge was counted in its place. ' + (tl.length ? (tl.every(x => /^none$/i.test(x.alt)) ? 'No alternate could be tried: ' + trWhy(tl[0]).replace(/^not seated: /, '') + '.' : 'Alternates tried: ' + tl.filter(x => !/^none$/i.test(x.alt)).map(x => nm(x.alt) + ', ' + trWhy(x)).join('; ') + '.') : 'No alternate was tried.') + '\n'; }); }
